(3168999, 445673, 6804, '<td valign="top">This is nice.  Good colors to keep it interesting and beautiful motion in the feathered lighting.  Clean and clear shot.   Good luck.</td>', 'This is nice.  Good colors to keep it interesting and beautiful motion in the feathered lighting.  Clean and clear shot.   Good luck.', '2007-01-02 01:58:47.000000', NULL, 1),
(3169012, 445333, 6804, '<td valign="top">This is a pretty good composition with the mountains lit up by the skiers and the landscape included in the burst of fire on the left.   I think the shot could improve with a little less brightness overall and maybe a bit of contrast.  I like the shot, but it just looks a little washed out to me.  I hope that helps some.   Good luck in the challenge.</td>', 'This is a pretty good composition with the mountains lit up by the skiers and the landscape included in the burst of fire on the left.   I think the shot could improve with a little less brightness overall and maybe a bit of contrast.  I like the shot, but it just looks a little washed out to me.  I hope that helps some.   Good luck in the challenge.', '2007-01-02 02:04:15.000000', NULL, 1),
(3169013, 445759, 66201, '<td valign="top">At first I was marvelling at the phallic nuances of this composition, but I think the close-up and capture is unique and striking nevertheless. 10</td>', 'At first I was marvelling at the phallic nuances of this composition, but I think the close-up and capture is unique and striking nevertheless. 10', '2007-01-02 02:04:40.000000', NULL, 1),
