(3181019, 445744, 42100, '<td valign="top">Yes, a differnet direction on the challenge...and a very well done photo to boot.  Good composition and use of DOF.  Very nice photograph!</td>', 'Yes, a differnet direction on the challenge...and a very well done photo to boot.  Good composition and use of DOF.  Very nice photograph!', '2007-01-04 13:55:29.000000', NULL, 1),
(3181020, 445682, 42100, '<td valign="top">Fantastic exposure and composition.  Very lively and well done photograph!</td>', 'Fantastic exposure and composition.  Very lively and well done photograph!', '2007-01-04 13:56:18.000000', NULL, 1),
(3181025, 445183, 42100, '<td valign="top">Rich colors in the fireworks, and very nice composition as well.  Great photo!</td>', 'Rich colors in the fireworks, and very nice composition as well.  Great photo!', '2007-01-04 13:57:39.000000', NULL, 1),
(3181027, 445363, 42100, '<td valign="top">Interesting combination the borealis and the fireworks.  Mother nature can put on quite a show herself.  Very nice photograph!</td>', 'Interesting combination the borealis and the fireworks.  Mother nature can put on quite a show herself.  Very nice photograph!', '2007-01-04 13:59:10.000000', NULL, 1),
