(3181042, 445759, 42100, '<td valign="top">Square crop was an excellent choice for this very good photograph.  Well composed with nice detail.  Well done!</td>', 'Square crop was an excellent choice for this very good photograph.  Well composed with nice detail.  Well done!', '2007-01-04 14:01:58.000000', NULL, 1),
(3181047, 445777, 42100, '<td valign="top">Very, very busy with all those fireworks.  But they all balance out nicely to not make the photograph itself too busy.  Great job!</td>', 'Very, very busy with all those fireworks.  But they all balance out nicely to not make the photograph itself too busy.  Great job!', '2007-01-04 14:04:06.000000', NULL, 1),
(3181048, 445148, 52449, '<td valign="top">Generally (IMO), fireworks should be in color.</td>', 'Generally (IMO), fireworks should be in color.', '2007-01-04 14:06:03.000000', NULL, 1),
(3181052, 446011, 42100, '<td valign="top">Very nice fireworks display there...in Italy.  Maybe a little more exposure, it would be nice to see some of what appears to be a city skyline.  It looks very interesting and would be a nice attribute to the photograph.</td>', 'Very nice fireworks display there...in Italy.  Maybe a little more exposure, it would be nice to see some of what appears to be a city skyline.  It looks very interesting and would be a nice attribute to the photograph.', '2007-01-04 14:07:39.000000', NULL, 1),
(3181053, 444898, 52449, '<td valign="top">Is it me, or is the horizon not level?</td>', 'Is it me, or is the horizon not level?', '2007-01-04 14:08:59.000000', NULL, 1),
(3181055, 445792, 42100, '<td valign="top">Crazy light and color in the photo, but it looks great.  This scene looks like some giant forest fire.  Very beautiful photograph!</td>', 'Crazy light and color in the photo, but it looks great.  This scene looks like some giant forest fire.  Very beautiful photograph!', '2007-01-04 14:09:28.000000', NULL, 1),
