(3186539, 445420, 60862, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2007-01-05 21:14:57.000000', NULL, 1),
(3186540, 446094, 27482, '<td valign="top">Well since I saw the other one, "Pink Toast" it´s hard to not compare this with that and I liked that shot better, mainly cause your fireworks are kindof blown out, especially through the glass and are more noisy.<br/> <br/>Still not a bad shot and I find it above average and voted 6.</td>', 'Well since I saw the other one, "Pink Toast" it´s hard to not compare this with that and I liked that shot better, mainly cause your fireworks are kindof blown out, especially through the glass and are more noisy. Still not a bad shot and I find it above average and voted 6.', '2007-01-05 21:15:15.000000', NULL, 1),
