(3201968, 445420, 22301, '<td valign="top">Great shot Robert, 2 new top scores in a few weeks, great work and congrats your red ribbon.</td>', 'Great shot Robert, 2 new top scores in a few weeks, great work and congrats your red ribbon.', '2007-01-09 21:25:32.000000', NULL, 0),
(3201974, 445363, 22301, '<td valign="top">Amazing shot, I love the blue night sky and the contrast of natural and manmade lightshows, congrats on your first ribbon!</td>', 'Amazing shot, I love the blue night sky and the contrast of natural and manmade lightshows, congrats on your first ribbon!', '2007-01-09 21:26:45.000000', NULL, 0),
