(3201985, 445682, 22301, '<td valign="top">Sweet shot Magnus and a b and white was a great choice, congrats on 5h place and another 7+ score.</td>', 'Sweet shot Magnus and a b and white was a great choice, congrats on 5h place and another 7+ score.', '2007-01-09 21:29:30.000000', NULL, 0),
