(3202275, 445420, 40797, '<td valign="top">Congratulations! This is FANTASTIC!</td>', 'Congratulations! This is FANTASTIC!', '2007-01-09 22:26:14.000000', NULL, 0),
(3202293, 445744, 52336, '<td valign="top">Nice idea. :)  I like the three angular sections of this photo, and all the textury stuff crossing those angles in various places.  Nice colour... kinda lonely feeling too.  Very nice.</td>', 'Nice idea. :)  I like the three angular sections of this photo, and all the textury stuff crossing those angles in various places.  Nice colour... kinda lonely feeling too.  Very nice.', '2007-01-09 22:29:50.000000', NULL, 0),
(3202467, 445420, 15305, '<td valign="top">Wow Bear!! This is so beautiful. Your photographic skills, both in the shooting and in the post processing are extraordinary.</td>', 'Wow Bear!! This is so beautiful. Your photographic skills, both in the shooting and in the post processing are extraordinary.', '2007-01-09 23:08:30.000000', NULL, 0),
(3202625, 445420, 65858, '<td valign="top">Great shot, Robert.  The near-perfect reflection is incredible!</td>', 'Great shot, Robert.  The near-perfect reflection is incredible!', '2007-01-09 23:27:29.000000', NULL, 0),
(3202681, 445420, 32872, '<td valign="top">Congratulations!  Your beautiful photos remind me of modern Norman Rockwell illustrations.  You always capture the perfect scene very nicely.  This image is no exception.<br/> <br/></td>', 'Congratulations!  Your beautiful photos remind me of modern Norman Rockwell illustrations.  You always capture the perfect scene very nicely.  This image is no exception. ', '2007-01-09 23:40:57.000000', NULL, 0),
(3202769, 445777, 34763, '<td valign="top">David, absolutely superb, a great pic and a super way to start the year, well done</td>', 'David, absolutely superb, a great pic and a super way to start the year, well done', '2007-01-10 00:09:03.000000', NULL, 0),
(3203305, 446122, 48451, '<td valign="top">Thanks for the votes! I, too, had hoped it would do a little better but I am happy it did as well as it did. To those of you who were worried about the possibility of setting the woods on fire, it had just finished raining for most of the day and the leaf mold on the ground was soaked. Not much chance of a fire! Thanks for your comments, I have a lot to think about and to try next time! ~Sharon</td>', 'Thanks for the votes! I, too, had hoped it would do a little better but I am happy it did as well as it did. To those of you who were worried about the possibility of setting the woods on fire, it had just finished raining for most of the day and the leaf mold on the ground was soaked. Not much chance of a fire! Thanks for your comments, I have a lot to think about and to try next time! ~Sharon', '2007-01-10 01:04:33.000000', NULL, 0),
(3204348, 445744, 31403, '<td valign="top">thank you for your refreshing originality in meeting this challenge</td>', 'thank you for your refreshing originality in meeting this challenge', '2007-01-10 05:48:43.000000', NULL, 0),
(3204702, 445799, 52130, '<td valign="top">very lovely, I gave this an 8. Great color and I love how you filled the frame</td>', 'very lovely, I gave this an 8. Great color and I love how you filled the frame', '2007-01-10 08:05:14.000000', NULL, 0),
(3204855, 445759, 65858, '<td valign="top">Very cool shot - neat idea, Crystal!</td>', 'Very cool shot - neat idea, Crystal!', '2007-01-10 08:40:50.000000', NULL, 0),
(3206802, 445363, 30490, '<td valign="top">All I can say is that Iceland has got to be one of the most photogenic places on earth!  I must visit one day for a long long stay to take as many photos as possible.  That and there are some damn fine photographers that are "grown" there.  Must be all that midnight sun in the summer and extensive night in the winter!  LOL.  Anyway this is an extremely creative and wonderfully executed image! Well done and congrats on winning the yellow ribbon!</td>', 'All I can say is that Iceland has got to be one of the most photogenic places on earth!  I must visit one day for a long long stay to take as many photos as possible.  That and there are some damn fine photographers that are "grown" there.  Must be all that midnight sun in the summer and extensive night in the winter!  LOL.  Anyway this is an extremely creative and wonderfully executed image! Well done and congrats on winning the yellow ribbon!', '2007-01-10 14:14:48.000000', NULL, 0),
(3206809, 445420, 30490, '<td valign="top">What can I say except that this image is stunning!  Well done, and you didn''t get beat by the Aurora! LOL</td>', 'What can I say except that this image is stunning!  Well done, and you didn''t get beat by the Aurora! LOL', '2007-01-10 14:16:05.000000', NULL, 0);
